let ctx,master,musicTimer,noiseSource;
const notes={acoustic:[48,55,60,64,55,60,67,64],jazz:[48,55,58,62,65,62,58,55],lofi:[45,52,55,59,62,59,55,52]};
export function stopAudio(){clearInterval(musicTimer);musicTimer=null;if(noiseSource){noiseSource.stop();noiseSource=null}if(master&&ctx)master.gain.setTargetAtTime(0,ctx.currentTime,.1)}
export function setAudio(settings,enabled=true){stopAudio();if(!enabled||settings.music==='off'&&settings.ambience==='quiet')return;try{ctx||=new (window.AudioContext||window.webkitAudioContext)();ctx.resume();master||=ctx.createGain();master.connect(ctx.destination);master.gain.setTargetAtTime(settings.volume/100*.22,ctx.currentTime,.15);
 if(settings.music!=='off'){let i=0,phrase=notes[settings.music]||notes.acoustic;const play=()=>{let now=ctx.currentTime;for(const [semitone,delay,gain] of [[phrase[i%8],0,.32],[phrase[(i+2)%8]+12,.14,.08]]){let osc=ctx.createOscillator(),amp=ctx.createGain();osc.type=settings.music==='lofi'?'sine':'triangle';osc.frequency.value=440*2**((semitone-69)/12);amp.gain.setValueAtTime(0,now+delay);amp.gain.linearRampToValueAtTime(gain,now+delay+.025);amp.gain.exponentialRampToValueAtTime(.001,now+delay+1.4);osc.connect(amp).connect(master);osc.start(now+delay);osc.stop(now+delay+1.5)}i++};play();musicTimer=setInterval(play,settings.music==='jazz'?590:760)}
 if(settings.ambience!=='quiet'){let buffer=ctx.createBuffer(1,ctx.sampleRate*3,ctx.sampleRate),data=buffer.getChannelData(0),last=0;for(let i=0;i<data.length;i++){last=(last+Math.random()*.04-.02)/1.02;data[i]=last}noiseSource=ctx.createBufferSource();noiseSource.buffer=buffer;noiseSource.loop=true;let filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=settings.ambience==='rain'?1500:450;noiseSource.connect(filter).connect(master);noiseSource.start()}
 }catch{}}
